const raw = $input.first().json;
let research;
try {
  research = typeof raw.researchData === 'string' ? JSON.parse(raw.researchData) : raw;
} catch (_) { research = raw; }

const { niche, etsy, amazon, pinterest, reddit, googleSearch, googleTrends, vision } = research;

// --- Helpers ---
const freq = (arr) => {
  const map = {};
  arr.filter(Boolean).forEach(v => { map[v] = (map[v] || 0) + 1; });
  return Object.entries(map).sort((a, b) => b[1] - a[1]).map(([k]) => k);
};

const normalize = s => (s || '').toLowerCase().trim();

// --- Titles & tags ---
const allTitles = [
  ...(etsy    || []).map(i => i.title),
  ...(amazon  || []).map(i => i.title),
  ...(reddit  || []).map(i => i.title)
].filter(Boolean);

const allTags = [
  ...(etsy    || []).flatMap(i => i.tags || []),
  ...(pinterest?.trendingKeywords || [])
].map(normalize).filter(Boolean);

// --- Vision signals ---
const allColors  = (vision || []).flatMap(i => i.colors  || []).map(normalize);
const allFonts   = (vision || []).map(i => i.fonts).filter(Boolean);
const allIcons   = (vision || []).flatMap(i => i.icons   || []).map(normalize);
const allLayouts = (vision || []).map(i => i.layout).filter(Boolean);
const allStyles  = (vision || []).map(i => i.style).filter(Boolean);
const allMoods   = (vision || []).map(i => i.mood).filter(Boolean);
const allTextures= (vision || []).map(i => i.texture).filter(Boolean);

// --- Google signals ---
const risingQueries   = (googleTrends?.risingQueries  || []);
const topQueries      = (googleTrends?.topQueries     || []);
const relatedSearches = (googleSearch?.relatedSearches || []);
const peopleAlsoAsk   = (googleSearch?.peopleAlsoAsk  || []);
const trendDirection  = googleTrends?.trendDirection  || 'stable';
const peakMonths      = googleTrends?.peakMonths      || [];
const lowMonths       = googleTrends?.lowMonths       || [];

// --- Audience: infer from reddit flairs and high-score post patterns ---
const redditPosts = (reddit || []).filter(p => p.score > 100);
const flairs = freq(redditPosts.map(p => p.flair).filter(Boolean));
const audienceSignals = [
  ...flairs.slice(0, 5),
  ...redditPosts
    .flatMap(p => (p.title || '').match(/\b(mom|dad|nurse|teacher|christian|cat|dog|gym|runner|veteran)\b/gi) || [])
    .map(s => s.toLowerCase())
];
const audience = freq(audienceSignals).slice(0, 8);

// --- Seasonality from Google Trends peaks ---
const monthNames = {
  '01':'January','02':'February','03':'March','04':'April',
  '05':'May','06':'June','07':'July','08':'August',
  '09':'September','10':'October','11':'November','12':'December'
};
const resolveMonth = m => {
  const num = m?.match(/(\d{2})$/)?.[1];
  return num ? (monthNames[num] || m) : m;
};
const seasonality = {
  peakMonths:  peakMonths.map(resolveMonth),
  lowMonths:   lowMonths.map(resolveMonth),
  trendDirection
};

// --- Competition signals ---
const etsyAvgFavs   = (etsy   || []).reduce((s, i) => s + (i.favCount || 0), 0) / Math.max((etsy   || []).length, 1);
const amazonAvgRev  = (amazon || []).reduce((s, i) => s + (i.reviews || 0), 0) / Math.max((amazon || []).length, 1);

const aggregated = {
  niche,
  colors:           freq(allColors).slice(0, 10),
  fonts:            freq(allFonts).slice(0, 5),
  icons:            freq(allIcons).slice(0, 15),
  layouts:          freq(allLayouts).slice(0, 5),
  styles:           freq(allStyles).slice(0, 5),
  moods:            freq(allMoods).slice(0, 5),
  textures:         freq(allTextures).slice(0, 5),
  keywords:         freq([...allTags, ...risingQueries, ...topQueries, ...relatedSearches]).slice(0, 30),
  quotes:           allTitles.slice(0, 20),
  audience,
  seasonality,
  competition: {
    etsyCount:       (etsy    || []).length,
    amazonCount:     (amazon  || []).length,
    etsyAvgFavs:     Math.round(etsyAvgFavs),
    amazonAvgReviews:Math.round(amazonAvgRev)
  },
  pinterestTrends:  (pinterest?.trendingKeywords || []).slice(0, 10),
  peopleAlsoAsk:    peopleAlsoAsk.slice(0, 10),
  aggregatedAt: new Date().toISOString()
};

return [{ json: aggregated }];
